steps.action:
curl -s -X POST "https://slack.com/api/conversations.list" -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/x-www-form-urlencoded" -d "types=public_channel&limit=1000" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for ch in data['channels']:
        if 'incident' in ch['name'].lower():
            print(json.dumps(ch, indent=2))
else:
    print('Error:', data)
"

curl -s -X POST "https://slack.com/api/conversations.history" -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/x-www-form-urlencoded" -d "channel=C_INC&limit=100" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for msg in data['messages']:
        text = msg.get('text','')
        if 'payment' in text.lower() and 'gateway' in text.lower():
            print(json.dumps(msg, indent=2))
else:
    print('Error:', data)
"

curl -s -X POST "https://slack.com/api/conversations.history" -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/x-www-form-urlencoded" -d "channel=C_INC&limit=100" | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for msg in data['messages']:
        print(f\"ts={msg['ts']} user={msg.get('user','')} text={msg.get('text','')[:100]}\")
else:
    print('Error:', data)
"
